package org.dpdns.gmm;
import static org.junit.Assert.*;
import android.content.Context;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w640dp-h320dp-land-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class NativeRoster60LibraryTest {
 final NativeHomePartyFeedbackTest helper=new NativeHomePartyFeedbackTest();
 @Before public void setup(){helper.isolate();helper.configure(NativeHomePartyFeedbackTest.PROFILES[0]);} @After public void restore(){helper.restore();}
 static class Api extends NativeApi {List<String> paths=new ArrayList<>();Api(Context c){super(c);}@Override String token(){return "roster-library-test";}@Override void call(String p,JSONObject b,Result cb){paths.add(p);if(p.endsWith("collection")){JSONArray chars=new JSONArray();for(int i=1;i<=60;i++)chars.put(MainActivity.obj("id",String.format(java.util.Locale.ROOT,"u%02d",i),"name","개체"+i,"rarity",i<=8?"COMMON":"RARE","ownedCount",i==1?1:0,"levelOneStats",MainActivity.obj("hp",10,"mp",5,"durability",3,"statusResistance",2,"speed",1),"suitability",MainActivity.obj("NORMAL",2),"defense",MainActivity.obj("NORMAL","resist"),"skills",new JSONArray()));cb.done(MainActivity.obj("characters",chars,"grades",MainActivity.obj("COMMON","커먼","RARE","레어"),"testBaseline",true),null);}else if(p.endsWith("recruit"))cb.done(MainActivity.obj("credits",30,"catalogVersion","fixture","offers",new JSONArray().put(MainActivity.obj("kind","LOW","label","하급","cost",2,"enabled",true)).put(MainActivity.obj("kind","MID","label","중급","cost",3,"enabled",false))),null);else cb.done(new JSONObject(),null);}}
 @Test public void actualProductEntriesUseNewAPIAndSingleCardFilter()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;h.state.put("tutorial",MainActivity.obj("flow","roster60-v1"));h.collection();assertTrue(api.paths.contains("native/roster60/collection"));NativeRoster60Library lib=new NativeRoster60Library(h);lib.collection();assertEquals(60,lib.visible.length());assertNotNull(lib.art.getDrawable());lib.grade="COMMON";lib.filter();assertEquals(8,lib.visible.length());lib.ownedOnly=true;lib.filter();assertEquals(1,lib.visible.length());assertTrue(lib.map(MainActivity.obj("NORMAL","resist")).contains("일반 내성"));lib.art.performLongClick();assertTrue(lib.message.getText().toString().contains("길게"));MotionEvent cancel=MotionEvent.obtain(0,0,MotionEvent.ACTION_CANCEL,0,0,0);lib.art.dispatchTouchEvent(cancel);cancel.recycle();assertFalse(lib.message.getText().toString().contains("동안"));helper.layout(h,NativeHomePartyFeedbackTest.PROFILES[0]);assertTrue(lib.art.getHeight()>0);h.draw();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(api.paths.contains("native/roster60/recruit"));
 // 예전 모집소 화면(트레이·수량)으로 새 60종을 모집한다. 확률 승인 전 중급은 고를 수 있어도 모집 버튼이 막힌다.
 h.root.findViewWithTag("draw-card-MID").performClick();Button go=h.root.findViewWithTag("draw-submit");assertFalse(go.isEnabled());assertEquals("승인 대기",go.getText().toString());assertFalse(api.paths.contains("draw"));}}
}
